const fp = require('fastify-plugin');

async function regionalPlugin(fastify, opts) {
  // Define schema for input validation
  const schema = { body: { type: 'object', required: ['id'], properties: { id: { type: 'integer' } } } };
  // Apply schema to route within encapsulated scope
  fastify.post('/update', { schema }, async (req, reply) => {
    return { status: 'validated' };
  });
}

module.exports = fp(regionalPlugin);
